def check_all_bellman(game, costs):
    ok, bad = 0, []
    for s in costs:
        if s == game.goal or not np.isfinite(costs[s]):
            continue
        best = min(game.entry_cost(n) + costs[n] for n in game.neighbors(s))
        if abs(best - costs[s]) < 1e-9:
            ok += 1
        else:
            bad.append((s, costs[s], best))
    return ok, bad


ok, bad = check_all_bellman(game, costs)
total = game.rows * game.cols - 1
print(f"States satisfying the Bellman equation: {ok}/{total}")
if bad:
    print("Violations:", bad)
else:
    print("\nEvery single cell is self-consistent.")
    print("That is what 'solved the MDP' means - the table is a fixed point of the Bellman operator.")

